-- =====================================================================================
-- iNXT BrokerVerse - V1081 Data Migration: data object register and decisions (BRID 1.1a),
-- versioned code maps (BRID 3.1), extract layouts and their columns, data-quality rules, masking
-- rules and client survivorship rules (DATA_MIGRATION_DESIGN sections 2, 5, 7, 8, 9 and 13).
--   The register, layouts, map sets and rules are global (one catalogue for the programme). Their
--   rows at the end of this script are generated from the data requirements catalogue
--   (docs/deliverables/src/migration/dm_layouts.yaml, version 1.2): every environment starts with
--   the same register (objects PROPOSED, decided at gate G1 in the console), the layouts in force,
--   the map sets (entries come in approved versions), the rule catalogue and the masking rules.
--   No foreign keys to V8xx tables (targets are held as plain values).
-- =====================================================================================

create table mig_data_object (
    id                    bigint generated by default as identity primary key,
    version               bigint        not null default 0,
    code                  varchar(10)   not null unique,
    name                  varchar(120)  not null,
    category              varchar(20)   not null,
    source_systems        varchar(100)  not null,
    target                varchar(300)  not null,
    business_owner        varchar(50),
    data_steward          varchar(50),
    owner_title           varchar(200),
    steward_title         varchar(200),
    day1_need             boolean       not null default false,
    day1_note             varchar(300),
    compliance_need       boolean       not null default false,
    compliance_note       varchar(300),
    archival_option       boolean       not null default false,
    archival_note         varchar(300),
    data_trust            varchar(10)   not null default 'MEDIUM',
    proposed_class        varchar(20)   not null,
    decided_class         varchar(20),
    condition_text        varchar(500),
    condition_met         boolean       not null default false,
    depends_on            varchar(200),
    load_order            integer       not null,
    financial             boolean       not null default false,
    rationale             varchar(2000) not null,
    status                varchar(20)   not null default 'PROPOSED',
    decided_at            timestamptz,
    decided_by            varchar(50),
    created_at            timestamptz   not null,
    created_by            varchar(50)   not null,
    updated_at            timestamptz,
    updated_by            varchar(50),
    constraint ck_mig_object_class check (proposed_class in ('MIGRATE', 'CARRY_FORWARD', 'ARCHIVE', 'EXCLUDED', 'CONDITIONAL')),
    constraint ck_mig_object_decided check (decided_class is null or decided_class in ('MIGRATE', 'CARRY_FORWARD', 'ARCHIVE', 'EXCLUDED', 'CONDITIONAL')),
    constraint ck_mig_object_status check (status in ('PROPOSED', 'FOR_DECISION', 'DECIDED')),
    constraint ck_mig_object_trust check (data_trust in ('HIGH', 'MEDIUM', 'LOW')),
    constraint ck_mig_object_category check (category in ('REFERENCE', 'CLIENT', 'POLICY', 'OPEN_ITEM', 'GL', 'HISTORY'))
);

create table mig_object_decision (
    id              bigint generated by default as identity primary key,
    version         bigint        not null default 0,
    company_id      bigint        not null references org_company (id),
    decision_no     varchar(30)   not null unique,
    object_code     varchar(10)   not null references mig_data_object (code),
    proposed_class  varchar(20)   not null,
    condition_text  varchar(500),
    condition_met   boolean       not null default false,
    criteria        varchar(2000) not null,
    rationale       varchar(2000) not null,
    status          varchar(20)   not null,
    submitted_by    varchar(50)   not null,
    submitted_at    timestamptz   not null,
    decided_by      varchar(50),
    decided_at      timestamptz,
    return_reason   varchar(1000),
    created_at      timestamptz   not null,
    created_by      varchar(50)   not null,
    updated_at      timestamptz,
    updated_by      varchar(50),
    constraint ck_mig_decision_status check (status in ('FOR_DECISION', 'DECIDED', 'RETURNED'))
);
create index ix_mig_decision_object on mig_object_decision (object_code, submitted_at);

create table mig_code_map_set (
    id              bigint generated by default as identity primary key,
    version         bigint        not null default 0,
    code            varchar(60)   not null unique,
    name            varchar(200)  not null,
    target_domain   varchar(120)  not null,
    target_kind     varchar(20)   not null default 'FREE',
    target_ref      varchar(60),
    default_target  varchar(60),
    business_owner  varchar(50),
    data_steward    varchar(50),
    owner_title     varchar(200),
    steward_title   varchar(200),
    used_by         varchar(200),
    created_at      timestamptz   not null,
    created_by      varchar(50)   not null,
    updated_at      timestamptz,
    updated_by      varchar(50),
    constraint ck_mig_map_set_kind check (target_kind in ('FREE', 'LOV', 'INSURER', 'PRODUCT', 'LINE', 'COVER_TYPE',
        'BRANCH', 'SALES_UNIT', 'USER', 'GL_ACCOUNT', 'CURRENCY', 'PACKAGE', 'COST_CENTER', 'STATUS'))
);

create table mig_code_map_version (
    id              bigint generated by default as identity primary key,
    version         bigint        not null default 0,
    set_code        varchar(60)   not null references mig_code_map_set (code),
    version_no      integer       not null,
    status          varchar(20)   not null,
    comment         varchar(1000),
    return_reason   varchar(1000),
    submitted_by    varchar(50),
    submitted_at    timestamptz,
    approved_by     varchar(50),
    approved_at     timestamptz,
    created_at      timestamptz   not null,
    created_by      varchar(50)   not null,
    updated_at      timestamptz,
    updated_by      varchar(50),
    constraint uq_mig_map_version unique (set_code, version_no),
    constraint ck_mig_map_version_status check (status in ('DRAFT', 'SUBMITTED', 'APPROVED', 'SUPERSEDED'))
);
create unique index uq_mig_map_version_approved on mig_code_map_version (set_code) where status = 'APPROVED';

create table mig_code_map_entry (
    id                 bigint generated by default as identity primary key,
    version_id         bigint        not null references mig_code_map_version (id),
    source_system      varchar(10)   not null,
    legacy_code        varchar(80)   not null,
    legacy_description varchar(250),
    qualifier          varchar(20)   not null default '',
    qualifier_value    varchar(60)   not null default '',
    action             varchar(10)   not null,
    target_code        varchar(60),
    remarks            varchar(300),
    constraint uq_mig_map_entry unique (version_id, source_system, legacy_code, qualifier, qualifier_value),
    constraint ck_mig_map_entry_action check (action in ('MAP', 'DEFAULT', 'REJECT', 'CREATE')),
    constraint ck_mig_map_entry_target check (action <> 'MAP' or target_code is not null)
);
create index ix_mig_map_entry_code on mig_code_map_entry (version_id, legacy_code);

create table mig_layout (
    id              bigint generated by default as identity primary key,
    version         bigint        not null default 0,
    code            varchar(10)   not null,
    version_no      integer       not null,
    object_code     varchar(10)   not null references mig_data_object (code),
    title           varchar(200)  not null,
    key_columns     varchar(200)  not null,
    hash_rule       varchar(20)   not null,
    hash_columns    varchar(200),
    amount_columns  varchar(300),
    status          varchar(20)   not null,
    frozen_by       varchar(50),
    frozen_at       timestamptz,
    created_at      timestamptz   not null,
    created_by      varchar(50)   not null,
    updated_at      timestamptz,
    updated_by      varchar(50),
    constraint uq_mig_layout unique (code, version_no),
    constraint ck_mig_layout_status check (status in ('DRAFT', 'FROZEN', 'RETIRED')),
    constraint ck_mig_layout_hash check (hash_rule in ('DISTINCT_COUNT', 'ROW_COUNT', 'NUMERIC_SUM'))
);

create table mig_layout_column (
    id              bigint generated by default as identity primary key,
    layout_id       bigint        not null references mig_layout (id),
    seq             integer       not null,
    name            varchar(60)   not null,
    description     varchar(500)  not null,
    data_type       varchar(12)   not null,
    length          varchar(10),
    mandatory       varchar(1)    not null,
    allowed_values  varchar(300),
    map_set         varchar(60),
    format          varchar(120),
    example         varchar(120),
    target          varchar(200),
    validation      varchar(500),
    source_hint     varchar(200),
    constraint uq_mig_layout_column unique (layout_id, name),
    constraint ck_mig_layout_column_type check (data_type in ('TEXT', 'CODE', 'DATE', 'TIMESTAMP', 'AMOUNT', 'INTEGER', 'DECIMAL', 'FLAG')),
    constraint ck_mig_layout_column_mandatory check (mandatory in ('Y', 'N', 'C'))
);

create table mig_rule (
    id              bigint generated by default as identity primary key,
    version         bigint        not null default 0,
    code            varchar(10)   not null unique,
    layout_scope    varchar(40)   not null,
    columns         varchar(200)  not null,
    kind            varchar(20)   not null,
    description     varchar(500)  not null,
    severity        varchar(10)   not null,
    message         varchar(300)  not null,
    fixed_by        varchar(120),
    active          boolean       not null default true,
    created_at      timestamptz   not null,
    created_by      varchar(50)   not null,
    updated_at      timestamptz,
    updated_by      varchar(50),
    constraint ck_mig_rule_severity check (severity in ('ERROR', 'WARNING')),
    constraint ck_mig_rule_kind check (kind in ('MANDATORY', 'FORMAT', 'LOOKUP', 'UNIQUE', 'REFERENTIAL', 'CROSS_FIELD',
        'BALANCE', 'PLAUSIBILITY', 'DUPLICATE_CLIENT'))
);

create table mig_masking_rule (
    id              bigint generated by default as identity primary key,
    version         bigint        not null default 0,
    layout_code     varchar(10)   not null,
    column_name     varchar(60)   not null,
    rule            varchar(20)   not null,
    active          boolean       not null default true,
    created_at      timestamptz   not null,
    created_by      varchar(50)   not null,
    updated_at      timestamptz,
    updated_by      varchar(50),
    constraint uq_mig_masking_rule unique (layout_code, column_name),
    constraint ck_mig_masking_rule check (rule in ('PERSON_NAME', 'LAST_NAME', 'FIRST_NAME', 'CORPORATE_NAME',
        'ADDRESS', 'DIGITS', 'EMAIL', 'BIRTH_DATE', 'FREE_TEXT'))
);

create table mig_survivorship_rule (
    id              bigint generated by default as identity primary key,
    version         bigint        not null default 0,
    field           varchar(60)   not null unique,
    rule            varchar(20)   not null,
    source_priority varchar(100)  not null,
    created_at      timestamptz   not null,
    created_by      varchar(50)   not null,
    updated_at      timestamptz,
    updated_by      varchar(50),
    constraint ck_mig_survivorship check (rule in ('SOURCE_PRIORITY', 'LATEST'))
);

-- ---------- Catalogue (generated from the data requirements catalogue, version 1.2) ----------
-- Data objects as proposed; each is decided at gate G1 in the console.

-- Extract layouts, version 1 in force, and their columns.

-- Code map sets (entries come in versions approved by the business owner).

-- Data-quality rules; the checks are implemented under the rule code.

-- Columns masked before staging outside production.

-- Survivorship of merged clients: contact data from QPS first, billing data from EBIX first.
