insert into mig_data_object (code, name, category, source_systems, target, owner_title, steward_title, day1_need, day1_note, compliance_need, compliance_note, archival_option, archival_note, data_trust, proposed_class, condition_text, depends_on, load_order, financial, rationale, status, created_at, created_by) values ('P01', 'In-force policy headers', 'POLICY', 'EBIX,QPS', 'acc_account through AccountService.importLegacy (new)', 'Head, Operations', 'Operations data steward', true, 'Policies in force at T; at least every expiry from T to 31-May-2028 and every booked renewal term starting on or after T', false, null, false, null, 'MEDIUM', 'CONDITIONAL', 'Needed to locate active coverage, to endorse legacy invoices and to renew in BIBS; the scope condition is decided by BDOI. Whatever it is, every policy expiring from T to 31-May-2028 and every renewal term booked in legacy that starts on or after T are in scope, because the go-live renewal extraction works only from the headers. The legacy package is kept as given; it is remapped at Renewal sanitation.', 'C01,R04,R05', 7, false, 'Needed to locate active coverage, to endorse legacy invoices and to renew in BIBS; the scope condition is decided by BDOI. Whatever it is, every policy expiring from T to 31-May-2028 and every renewal term booked in legacy that starts on or after T are in scope, because the go-live renewal extraction works only from the headers. The legacy package is kept as given; it is remapped at Renewal sanitation.', 'PROPOSED', now(), 'SYSTEM');
